USE ExploreDB;
GO

-- Prevent accidental execution in master database
IF DB_NAME() = 'master'
BEGIN
    RAISERROR('Cannot run this script in master database. Please ensure ExploreDB is selected.', 16, 1);
    SET NOEXEC ON;
END
GO

-- Clean up any leftover copy from master (if user previously ran this while master was active)
IF OBJECT_ID('master.dbo.sp_GenerateUltimateDummyData', 'P') IS NOT NULL
BEGIN
    BEGIN TRY
        EXEC master.sys.sp_executesql N'IF OBJECT_ID(''dbo.sp_GenerateUltimateDummyData'', ''P'') IS NOT NULL DROP PROCEDURE dbo.sp_GenerateUltimateDummyData;';
    END TRY
    BEGIN CATCH
    END CATCH
END
GO

SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO

-- =======================================================================================
-- THE ULTIMATE MASSIVE DATA GENERATOR (5 Million+ / 50 Lakh Records)
-- Fully Idempotent & Re-runnable: Never fails on existing data or duplicate keys.
-- Uses usp_ prefix to avoid SQL Server master database system procedure resolution.
-- =======================================================================================
IF OBJECT_ID('dbo.usp_GenerateUltimateDummyData', 'P') IS NOT NULL
    DROP PROCEDURE dbo.usp_GenerateUltimateDummyData;
GO

CREATE PROCEDURE dbo.usp_GenerateUltimateDummyData
AS
BEGIN
    SET NOCOUNT ON;
    PRINT 'Initiating Ultimate Bulk Data Generation (5 Million+ records)...';

    -- 1. Base Config (Currencies, Languages, Roles)
    IF NOT EXISTS (SELECT 1 FROM dbo.Currencies WHERE CurrencyCode = 'USD')
        INSERT INTO dbo.Currencies (CurrencyCode, CurrencyName, Symbol) VALUES ('USD', 'US Dollar', '$'), ('EUR', 'Euro', N'€'), ('GBP', 'British Pound', N'£');

    IF NOT EXISTS (SELECT 1 FROM dbo.Languages WHERE LanguageCode = 'en-US')
        INSERT INTO dbo.Languages (LanguageCode, LanguageName) VALUES ('en-US', 'English'), ('es-ES', 'Spanish'), ('fr-FR', 'French');

    IF NOT EXISTS (SELECT 1 FROM dbo.Roles WHERE RoleName = 'Admin')
        INSERT INTO dbo.Roles (RoleName) VALUES ('Admin'), ('Customer'), ('Support'), ('Employee'), ('Affiliate');

    -- 2. Departments & Assembly Lines
    IF NOT EXISTS (SELECT 1 FROM dbo.Departments WHERE DepartmentName = 'HR')
        INSERT INTO dbo.Departments (DepartmentName) VALUES ('HR'), ('Engineering'), ('Sales'), ('Marketing'), ('Logistics'), ('Manufacturing');

    IF NOT EXISTS (SELECT 1 FROM dbo.AssemblyLines WHERE LineName = 'Alpha Line')
        INSERT INTO dbo.AssemblyLines (LineName) VALUES ('Alpha Line'), ('Beta Line'), ('Gamma Line');

    IF NOT EXISTS (SELECT 1 FROM dbo.ShippingCarriers WHERE CarrierName = 'FedEx')
    BEGIN
        INSERT INTO dbo.ShippingCarriers (CarrierName) VALUES ('FedEx'), ('UPS'), ('USPS'), ('DHL');
        INSERT INTO dbo.ShippingMethods (CarrierID, MethodName, BaseCost, EstimatedDays) 
        SELECT CarrierID, 'Standard Ground', 5.99, 5 FROM dbo.ShippingCarriers UNION ALL
        SELECT CarrierID, '2-Day Express', 15.99, 2 FROM dbo.ShippingCarriers UNION ALL
        SELECT CarrierID, 'Overnight Priority', 29.99, 1 FROM dbo.ShippingCarriers;
    END

    -- 3. Warehouses
    IF NOT EXISTS (SELECT 1 FROM dbo.Warehouses WHERE WarehouseCode = 'WH1')
    BEGIN
        DECLARE @w INT = 1; 
        WHILE @w <= 10 
        BEGIN 
            INSERT INTO dbo.Warehouses (WarehouseCode, LocationName, City, Country) 
            VALUES ('WH' + CAST(@w AS VARCHAR), 'Mega Warehouse ' + CAST(@w AS VARCHAR), 'Metropolis', 'USA'); 
            SET @w = @w + 1; 
        END
    END

    -- 4. Vehicles
    IF NOT EXISTS (SELECT 1 FROM dbo.VehicleFleet)
    BEGIN
        DECLARE @v INT = 1; 
        WHILE @v <= 100 
        BEGIN 
            INSERT INTO dbo.VehicleFleet (LicensePlate, VehicleType) 
            VALUES ('TRK-' + LEFT(CAST(NEWID() AS VARCHAR(36)), 8), CASE WHEN @v%2=0 THEN 'Truck' ELSE 'Van' END); 
            SET @v = @v + 1; 
        END
    END

    -- 5. Brands & Categories
    IF NOT EXISTS (SELECT 1 FROM dbo.Brands)
    BEGIN
        DECLARE @b INT = 1; 
        WHILE @b <= 200 
        BEGIN 
            INSERT INTO dbo.Brands (BrandName) VALUES ('Global Brand ' + CAST(NEWID() AS VARCHAR(36))); 
            INSERT INTO dbo.Categories (CategoryName) VALUES ('Global Category ' + CAST(NEWID() AS VARCHAR(36))); 
            SET @b = @b + 1; 
        END
    END

    -- 6. Products (20,000)
    DECLARE @ExistingProductCount INT = (SELECT COUNT(*) FROM dbo.Products);
    IF @ExistingProductCount < 20000
    BEGIN
        PRINT 'Generating Products up to 20,000...';
        DECLARE @p INT = @ExistingProductCount + 1;
        WHILE @p <= 20000
        BEGIN
            INSERT INTO dbo.Products (CategoryID, BrandID, ProductName, SKU, BasePrice) 
            VALUES ((@p % 199) + 1, (@p % 199) + 1, 'Ultimate Item ' + CAST(@p AS VARCHAR), 'SKU-' + CAST(NEWID() AS VARCHAR(36)), ROUND((@p * 17.3) % 990 + 10.0, 2));
            SET @p = @p + 1;
        END
    END

    -- Ensure top 50 products have Overlay_Image (PNG and JPEG samples for image badge & viewer testing)
    UPDATE dbo.Products 
    SET Overlay_Image = CASE 
        WHEN (ProductID % 2) = 1 THEN  
        ELSE  
    END
    WHERE ProductID <= 50 AND Overlay_Image IS NULL;

    -- 7. Inventory Distribution across Warehouses
    IF NOT EXISTS (SELECT 1 FROM dbo.WarehouseInventory)
    BEGIN
        PRINT 'Distributing Inventory across Warehouses (40,000 records)...';
        INSERT INTO dbo.WarehouseInventory (WarehouseID, ProductID, StockQuantity) 
        SELECT (ProductID % 10) + 1, ProductID, CAST(RAND(ProductID) * 5000 AS INT) + 100 
        FROM dbo.Products;

        INSERT INTO dbo.WarehouseInventory (WarehouseID, ProductID, StockQuantity) 
        SELECT ((ProductID+1) % 10) + 1, ProductID, CAST(RAND(ProductID) * 2000 AS INT) + 50 
        FROM dbo.Products;
    END

    -- 8. Raw Materials & BOM
    IF NOT EXISTS (SELECT 1 FROM dbo.RawMaterials)
    BEGIN
        PRINT 'Generating Raw Materials & Bill of Materials...';
        DECLARE @rm INT = 1;
        WHILE @rm <= 500
        BEGIN
            INSERT INTO dbo.RawMaterials (MaterialName, UnitOfMeasure, CostPerUnit)
            VALUES ('Material ' + CAST(@rm AS VARCHAR), 'kg', ROUND((@rm * 3.7) % 50 + 1.0, 2));
            SET @rm = @rm + 1;
        END

        INSERT INTO dbo.BillOfMaterials (ProductID, MaterialID, QuantityRequired) 
        SELECT TOP 10000 ProductID, (ProductID % 500) + 1, ROUND((ProductID * 1.5) % 10 + 0.5, 2) 
        FROM dbo.Products;
    END

    -- 9. Users (20,000)
    DECLARE @ExistingUserCount INT = (SELECT COUNT(*) FROM dbo.Users);
    IF @ExistingUserCount < 20000
    BEGIN
        PRINT 'Generating Users up to 20,000...';
        DECLARE @u INT = @ExistingUserCount + 1;
        WHILE @u <= 20000
        BEGIN
            INSERT INTO dbo.Users (FirstName, LastName, Email, PasswordHash, PreferredLanguageID, PreferredCurrencyID) 
            VALUES ('MegaUserFn_' + CAST(@u AS VARCHAR), 'MegaUserLn_' + CAST(@u AS VARCHAR), 'user' + CAST(@u AS VARCHAR) + '@mega.com', HASHBYTES('SHA2_256', 'Pass_' + CAST(@u AS VARCHAR)), (@u % 3) + 1, (@u % 3) + 1);
            SET @u = @u + 1;
        END
    END

    -- Ensure top 20 users have ProfilePicture (PNG)
    UPDATE dbo.Users
    SET ProfilePicture = 
    WHERE UserID <= 20 AND ProfilePicture IS NULL;

    -- 10. Employees (1,000)
    IF NOT EXISTS (SELECT 1 FROM dbo.Employees)
    BEGIN
        INSERT INTO dbo.Employees (UserID, DepartmentID, JobTitle, HireDate, BaseSalary) 
        SELECT TOP 1000 
            UserID, 
            (UserID % 6) + 1, 
            'Enterprise Staff', 
            DATEADD(DAY, -CAST((UserID * 7) % 1000 AS INT), GETDATE()), 
            50000 + ((UserID * 13) % 50000) 
        FROM dbo.Users 
        ORDER BY UserID;
    END

    -- 11. Affiliates (500)
    IF NOT EXISTS (SELECT 1 FROM dbo.Affiliates)
    BEGIN
        INSERT INTO dbo.Affiliates (UserID, AffiliateCode) 
        SELECT TOP 500 
            UserID, 
            'AFF-' + CAST(UserID AS VARCHAR) 
        FROM dbo.Users 
        WHERE UserID NOT IN (SELECT UserID FROM dbo.Employees);
    END

    -- 12. Quality Inspections (10,000)
    IF NOT EXISTS (SELECT 1 FROM dbo.QualityInspections)
    BEGIN
        DECLARE @InspectorEmpID INT = (SELECT TOP 1 EmployeeID FROM dbo.Employees);
        INSERT INTO dbo.QualityInspections (ProductID, AssemblyLineID, InspectorEmployeeID, Passed, DefectReason) 
        SELECT TOP 10000 
            ProductID, 
            (ProductID % 3) + 1, 
            @InspectorEmpID, 
            CASE WHEN (ProductID % 15) = 0 THEN 0 ELSE 1 END, 
            CASE WHEN (ProductID % 15) = 0 THEN 'Failed Tolerance Test' ELSE NULL END 
        FROM dbo.Products;
    END

    -- 13. Ensure MassiveDataTest exists with 5,000,000 seed rows
    IF OBJECT_ID('dbo.MassiveDataTest', 'U') IS NULL OR (SELECT COUNT_BIG(*) FROM dbo.MassiveDataTest) < 5000000
    BEGIN
        PRINT 'Generating dbo.MassiveDataTest seed data (5,000,000 records)...';
        IF OBJECT_ID('dbo.sp_GenerateMassiveDataVolume', 'P') IS NOT NULL
            EXEC dbo.sp_GenerateMassiveDataVolume;
    END

    -- 14. Orders (5,000,000 / 50 Lakh records)
    DECLARE @TotalOrdersNow BIGINT = (SELECT COUNT_BIG(*) FROM dbo.Orders);
    IF @TotalOrdersNow < 5000000
    BEGIN
        DECLARE @OrdersNeeded BIGINT = 5000000 - @TotalOrdersNow;
        PRINT 'Generating ' + CAST(@OrdersNeeded AS VARCHAR) + ' Orders to reach 5,000,000 total...';
        
        ALTER TABLE dbo.Orders NOCHECK CONSTRAINT ALL;

        DECLARE @BatchSize INT = 25000;
        DECLARE @UserCount INT = (SELECT COUNT(*) FROM dbo.Users);
        IF @UserCount = 0 SET @UserCount = 1;
        DECLARE @AffiliateCount INT = (SELECT COUNT(*) FROM dbo.Affiliates);

        WHILE @TotalOrdersNow < 5000000
        BEGIN
            INSERT INTO dbo.Orders WITH (TABLOCK) 
                (OrderID, UserID, OrderDate, SubTotal, TotalAmount, AffiliateID, Status)
            SELECT TOP (@BatchSize)
                NEWID(),
                (RowID % @UserCount) + 1,
                DateLogged,
                RandomValue,
                CAST(RandomValue * 1.08 AS DECIMAL(18,2)),
                CASE WHEN @AffiliateCount > 0 AND (RowID % 10 = 0) THEN (RowID % @AffiliateCount) + 1 ELSE NULL END,
                CASE StatusFlag WHEN 1 THEN 'Completed' ELSE 'Processing' END
            FROM dbo.MassiveDataTest
            WHERE RowID > (@TotalOrdersNow % 5000000) 
              AND RowID <= (@TotalOrdersNow % 5000000) + @BatchSize;

            SET @TotalOrdersNow = @TotalOrdersNow + @BatchSize;
        END

        ALTER TABLE dbo.Orders CHECK CONSTRAINT ALL;
        PRINT 'dbo.Orders generation complete! Total: 5,000,000 orders.';
    END
    ELSE
    BEGIN
        PRINT 'dbo.Orders already contains ' + CAST(@TotalOrdersNow AS VARCHAR) + ' records. Skipping generation.';
    END

    -- 15. Order Details (100,000 line items linked to orders)
    IF NOT EXISTS (SELECT 1 FROM dbo.OrderDetails)
    BEGIN
        PRINT 'Generating 100,000 OrderDetails...';
        ALTER TABLE dbo.OrderDetails NOCHECK CONSTRAINT ALL;

        DECLARE @ProdCount INT = (SELECT COUNT(*) FROM dbo.Products);
        IF @ProdCount = 0 SET @ProdCount = 1;

        INSERT INTO dbo.OrderDetails WITH (TABLOCK) (OrderID, ProductID, WarehouseID, Quantity, UnitPrice)
        SELECT 
            o.OrderID,
            (ROW_NUMBER() OVER(ORDER BY (SELECT NULL)) % @ProdCount) + 1,
            (ROW_NUMBER() OVER(ORDER BY (SELECT NULL)) % 10) + 1,
            (ROW_NUMBER() OVER(ORDER BY (SELECT NULL)) % 4) + 1,
            CAST(((ROW_NUMBER() OVER(ORDER BY (SELECT NULL)) * 7) % 200) + 9.99 AS DECIMAL(18,2))
        FROM (SELECT TOP (100000) OrderID FROM dbo.Orders) AS o;

        ALTER TABLE dbo.OrderDetails CHECK CONSTRAINT ALL;
    END

    -- 16. Page Views (100,000 analytics hits)
    IF NOT EXISTS (SELECT 1 FROM dbo.PageViews)
    BEGIN
        PRINT 'Generating 100,000 PageViews (Analytics)...';
        DECLARE @pv INT = 1; 
        WHILE @pv <= 100000 
        BEGIN 
            INSERT INTO dbo.PageViews (SessionID, PageURL, UserAgent) 
            VALUES ('SESSION_' + CAST((@pv % 1000) AS VARCHAR), '/products/item-' + CAST((@pv % 20000) AS VARCHAR), CASE WHEN @pv%3=0 THEN 'Mozilla/5.0 (iPhone)' ELSE 'Mozilla/5.0 (Windows NT 10.0)' END); 
            SET @pv = @pv + 1; 
        END
    END

    PRINT 'Ultimate Data Generation Complete! DB is heavily populated.';
END
GO

-- =======================================================================================
-- Backward-compatibility wrapper for sp_GenerateUltimateDummyData
-- =======================================================================================
IF OBJECT_ID('dbo.sp_GenerateUltimateDummyData', 'P') IS NOT NULL
    DROP PROCEDURE dbo.sp_GenerateUltimateDummyData;
GO

CREATE PROCEDURE dbo.sp_GenerateUltimateDummyData
AS
BEGIN
    SET NOCOUNT ON;
    EXEC dbo.usp_GenerateUltimateDummyData;
END
GO

-- =======================================================================================
-- Execute Data Generation
-- =======================================================================================
EXEC dbo.usp_GenerateUltimateDummyData;
GO

